    private BigDecimal calcularSubtotal(List<ItemRequest> itens, String cupom) {
        BigDecimal subtotal = BigDecimal.ZERO;

        for (ItemRequest item : itens) {
            BigDecimal precoItem = BigDecimal.valueOf(item.getPrecoUnitario());
            int quantidade = item.getQuantidade();

            if ("LEVE3PAGUE2".equals(cupom)) {
                int trios = quantidade / 3;
                int sobra = quantidade % 3;
                int quantidadePaga = trios * 2 + sobra;
                subtotal = subtotal.add(
