    private BigDecimal calcularFrete(String modalidade, List<ItemRequest> itens, String cupom) {
        if ("FRETEGRATIS".equals(cupom)) {
            return BigDecimal.ZERO;
        }

        Modalidade m = Modalidade.fromCodigo(modalidade);
        if (m == null) {
